        # Construct the adjacency matrix
        A = [[0] * n for _ in range(n)]
        for u, v in edges:
            A[u][v] = 1
            A[v][u] = 1

        # Perform Gaussian elimination to find the rank of the matrix
        rank = 0
        for i in range(n):
            if all(A[j][i] == 0 for j in range(i, n)):
                continue
            rank += 1
            pivot_row = next(j for j in range(i, n) if A[j][i] != 0)
